    50	int ares_parse_a_reply(const unsigned char *abuf, int alen,
    51	                       struct hostent **host,
    52	                       struct ares_addrttl *addrttls, int *naddrttls)
    53	{
    54	  struct ares_addrinfo ai;
    55	  struct ares_addrinfo_node *next;
    56	  struct ares_addrinfo_cname *next_cname;
    57	  char **aliases = NULL;
    58	  char *question_hostname = NULL;
    59	  struct hostent *hostent = NULL;
    60	  struct in_addr *addrs = NULL;
    61	  int naliases = 0, naddrs = 0, alias = 0, i;
    62	  int cname_ttl = INT_MAX;
    63	  int status;
    64	
    65	  memset(&ai, 0, sizeof(ai));
    66	
    67	  status = ares__parse_into_addrinfo2(abuf, alen, &question_hostname, &ai);
    68	  if (status != ARES_SUCCESS)
    69	    {
    70	      ares_free(question_hostname);
    71	
    72	      if (naddrttls)
    73	        {
    74	          *naddrttls = naddrs;
    75	        }
    76	
    77	      return status;
    78	    }
    79	
    80	  hostent = ares_malloc(sizeof(struct hostent));
    81	  if (!hostent)
    82	    {
    83	      goto enomem;
    84	    }
    85	
    86	  next = ai.nodes;
    87	  while (next)
    88	    {
    89	      ++naddrs;
    90	      next = next->ai_next;
    91	    }
    92	
    93	  next_cname = ai.cnames;
    94	  while (next_cname)
    95	    {
    96	      if(next_cname->alias)
    97	        ++naliases;
    98	      next_cname = next_cname->next;
    99	    }
   100	
   101	  aliases = ares_malloc((naliases + 1) * sizeof(char *));
   102	  if (!aliases)
   103	    {
   104	      goto enomem;
   105	    }
   106	
   107	  if (naliases)
   108	    {
   109	      next_cname = ai.cnames;
   110	      while (next_cname)
   111	        {
   112	          if(next_cname->alias)
   113	            aliases[alias++] = strdup(next_cname->alias);
   114	          if(next_cname->ttl < cname_ttl)
   115	            cname_ttl = next_cname->ttl;
   116	          next_cname = next_cname->next;
   117	        }
   118	    }
   119	
   120	  aliases[alias] = NULL;
   121	
   122	  hostent->h_addr_list = ares_malloc((naddrs + 1) * sizeof(char *));
   123	  if (!hostent->h_addr_list)
   124	    {
   125	      goto enomem;
   126	    }
   127	
   128	  if (ai.cnames)
   129	    {
   130	      hostent->h_name = strdup(ai.cnames->name);
   131	      ares_free(question_hostname);
   132	    }
   133	  else
   134	    {
   135	      hostent->h_name = question_hostname;
   136	    }
   137	
   138	  hostent->h_aliases = aliases;
   139	  hostent->h_addrtype = AF_INET;
   140	  hostent->h_length = sizeof(struct in_addr);
   141	
   142	  if (naddrs)
   143	    {
   144	      addrs = ares_malloc(naddrs * sizeof(struct in_addr));
   145	      if (!addrs)
   146	        {
   147	          goto enomem;
   148	        }
   149	
   150	      next = ai.nodes;
   151	      for (i = 0; i < naddrs; i++)
   152	        {
   153	          hostent->h_addr_list[i] = (char*)&addrs[i];
   154	          memcpy(hostent->h_addr_list[i], &(((struct sockaddr_in *)next->ai_addr)->sin_addr), sizeof(struct in_addr));
   155	          if (naddrttls)
   156	            {
   157	                if(next->ai_ttl > cname_ttl)
   158	                  addrttls[i].ttl = cname_ttl;
   159	                else
   160	                  addrttls[i].ttl = next->ai_ttl;
   161	
   162	                memcpy(&addrttls[i].ipaddr, &(((struct sockaddr_in *)next->ai_addr)->sin_addr), sizeof(struct in_addr));
   163	            }
   164	          next = next->ai_next;
   165	        }
   166	    }
   167	
   168	  hostent->h_addr_list[naddrs] = NULL;
   169	
   170	  if (host)
   171	    {
   172	      *host = hostent;
   173	    }
   174	  else
   175	    {
   176	      ares_free_hostent(hostent);
   177	    }
   178	
   179	  if (naddrttls)
   180	    {
   181	      *naddrttls = naddrs;
   182	    }
   183	
   184	  ares__freeaddrinfo_cnames(ai.cnames);
   185	  ares__freeaddrinfo_nodes(ai.nodes);
   186	  return ARES_SUCCESS;
   187	
   188	enomem:
   189	  ares_free(aliases);
   190	  ares_free(hostent);
   191	  ares__freeaddrinfo_cnames(ai.cnames);
   192	  ares__freeaddrinfo_nodes(ai.nodes);
   193	  ares_free(question_hostname);
   194	  return ARES_ENOMEM;
   195	}
